-- MathLabs v29.0 → v29.4 · 5B REVIEWED RC2 · CONSOLIDATED STAGING INSTALL
-- 27 OA · 54 topics · 216 nodes · deep content · 1404 assessment items · adaptive · diagnostic · routes.
-- RC2: contract-audited content. No publication controller. No live student delivery.
begin;
select public.mathlabs_assert_admin_v22();

do $$
begin
 if (select count(*) from public.courses where id='cl-5-basico')<>1 then raise exception 'Preflight v29.0: cl-5-basico no existe en public.courses'; end if;
 if to_regclass('public.mathlabs_course_catalog_v259') is null
    or to_regclass('public.multigrade_assessment_items_v261') is null
    or to_regclass('public.multigrade_adaptive_item_metadata_v262') is null
    or to_regclass('public.multigrade_diagnostic_blueprints_v263') is null
    or to_regclass('public.multigrade_learning_route_contract_v264') is null
    or to_regclass('public.multigrade_assessment_certification_v264') is null
    or to_regclass('public.multigrade_assessment_readiness_v264') is null
    or to_regclass('public.multigrade_curriculum_source_snapshot_v269') is null
    or to_regclass('public.multigrade_course_runtime_gate_v269') is null then
   raise exception 'Falta arquitectura V25.9-V27.9 requerida por 5B';
 end if;
 if (select count(*) from public.mathlabs_course_catalog_v259 where course_id='cl-5-basico')<>1 then
   raise exception 'cl-5-basico no está registrado en V25.9';
 end if;
 if exists(select 1 from public.curriculum_sources_v254 where course_id='cl-5-basico')
or exists(select 1 from public.curriculum_oas_v254 where course_id='cl-5-basico')
or exists(select 1 from public.curriculum_axes where course_id='cl-5-basico')
or exists(select 1 from public.curriculum_objectives where course_id='cl-5-basico')
or exists(select 1 from public.knowledge_topics where course_id='cl-5-basico')
or exists(select 1 from public.deep_learning_paths_v250 where course_id='cl-5-basico')
or exists(select 1 from public.curriculum_nodes_v254 where course_id='cl-5-basico')
or exists(select 1 from public.curriculum_coverage_v254 where course_id='cl-5-basico')
or exists(select 1 from public.curriculum_topic_readiness_v254 where course_id='cl-5-basico')
or exists(select 1 from public.multigrade_assessment_items_v261 where course_id='cl-5-basico')
or exists(select 1 from public.multigrade_review_sets_v261 where course_id='cl-5-basico')
or exists(select 1 from public.multigrade_adaptive_item_metadata_v262 where course_id='cl-5-basico')
or exists(select 1 from public.multigrade_diagnostic_blueprints_v263 where course_id='cl-5-basico')
or exists(select 1 from public.multigrade_learning_route_contract_v264 where course_id='cl-5-basico')
or exists(select 1 from public.multigrade_assessment_certification_v264 where course_id='cl-5-basico')
or exists(select 1 from public.multigrade_assessment_readiness_v264 where course_id='cl-5-basico')
or exists(select 1 from public.multigrade_curriculum_source_snapshot_v269 where course_id='cl-5-basico')
or exists(select 1 from public.multigrade_course_runtime_gate_v269 where course_id='cl-5-basico') then
          raise exception 'v29.0-v29.4 5B RC2 detectó artefactos previos; no instalar sobre un estado parcial';
        end if;

 if (select count(*) from public.deep_learning_paths_v250 where course_id='cl-8-basico' and content_version='v27.5' and status='staging')<>34
   or (select count(*) from public.curriculum_nodes_v254 where course_id='cl-8-basico' and is_active)<>136
   or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-8-basico')<>884
   or exists(select 1 from public.deep_learning_paths_v250 where course_id='cl-8-basico' and status='published')
   or exists(select 1 from public.multigrade_assessment_items_v261 where course_id='cl-8-basico' and is_published)
   or coalesce((select live_student_delivery from public.multigrade_course_runtime_gate_v269 where course_id='cl-8-basico'),true) then
  raise exception 'Baseline cl-8-basico alterado antes de instalar 5B';
end if;

if (select count(*) from public.deep_learning_paths_v250 where course_id='cl-7-basico' and content_version='v28.0' and status='staging')<>38
   or (select count(*) from public.curriculum_nodes_v254 where course_id='cl-7-basico' and is_active)<>152
   or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-7-basico')<>988
   or exists(select 1 from public.deep_learning_paths_v250 where course_id='cl-7-basico' and status='published')
   or exists(select 1 from public.multigrade_assessment_items_v261 where course_id='cl-7-basico' and is_published)
   or coalesce((select live_student_delivery from public.multigrade_course_runtime_gate_v269 where course_id='cl-7-basico'),true) then
  raise exception 'Baseline cl-7-basico alterado antes de instalar 5B';
end if;

if (select count(*) from public.deep_learning_paths_v250 where course_id='cl-6-basico' and content_version='v28.5' and status='staging')<>48
   or (select count(*) from public.curriculum_nodes_v254 where course_id='cl-6-basico' and is_active)<>192
   or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-6-basico')<>1248
   or exists(select 1 from public.deep_learning_paths_v250 where course_id='cl-6-basico' and status='published')
   or exists(select 1 from public.multigrade_assessment_items_v261 where course_id='cl-6-basico' and is_published)
   or coalesce((select live_student_delivery from public.multigrade_course_runtime_gate_v269 where course_id='cl-6-basico'),true) then
  raise exception 'Baseline cl-6-basico alterado antes de instalar 5B';
end if;

 if (select count(*) from public.deep_learning_paths_v250 where course_id='cl-1-medio' and content_version='v27.0' and status='staging')<>30
    or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-1-medio')<>780
    or (select count(*) from public.deep_learning_paths_v250 where course_id='cl-2-medio' and content_version='v26.5' and status='staging')<>24
    or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-2-medio')<>624
    or (select count(*) from public.deep_learning_paths_v250 where course_id='cl-3-medio' and content_version='v26.0' and status='staging')<>24
    or (select count(*) from public.multigrade_assessment_items_v261 where course_id='cl-3-medio')<>624
    or (select count(*) from public.deep_learning_paths_v250 where course_id='cl-4-medio' and status='staging')<>24
    or (select count(*) from public.school_practice_items where code like '4M-V225-P-%' and is_published)<>480
    or (select count(*) from public.school_diagnostic_items where diagnostic_version='4m-fg-v225' and is_published)<>72
    or (select count(*) from public.school_review_items where code like '4M-V225-R-%' and is_published)<>72
    or (select count(*) from public.school_review_sets where id like '4m-fg-v225-%' and is_published)<>4
    or (select count(*) from public.content_releases_v240 where release_key='4m-v240' and status='applied')<>1 then
   raise exception 'Baseline 1M-4M/V24 alterado antes de instalar 5B';
 end if;
end $$;

-- v29.0 · curriculum and deep authoring --------------------------------
insert into public.multigrade_curriculum_source_snapshot_v269(
 course_id,snapshot_date,curriculum_basis,course_url,program_url,update_process_url,
 update_process_status,requires_revalidation_before_release
) values('cl-5-basico','2026-08-12','Currículo oficial de Matemática 5.º básico actualmente publicado',
 'https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico','https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-5-basico','https://www.curriculumnacional.cl/actualizacion-curricular','monitoring',true)
on conflict(course_id) do update set snapshot_date=excluded.snapshot_date,curriculum_basis=excluded.curriculum_basis,
 course_url=excluded.course_url,program_url=excluded.program_url,update_process_url=excluded.update_process_url,
 update_process_status='monitoring',requires_revalidation_before_release=true,revalidated_at=null,revalidated_by=null,
 revalidation_notes=null,updated_at=now();

insert into public.multigrade_course_runtime_gate_v269(
 course_id,content_version,assessment_version,adaptive_calibration_status,human_content_review_required,
 human_assessment_review_required,live_student_delivery,release_candidate,blocker_codes
) values('cl-5-basico','v29.0','v29.1','heuristic_candidate',true,true,false,false,
 '["CURRICULUM_REVALIDATION_REQUIRED_BEFORE_RELEASE","HUMAN_CONTENT_REVIEW_PENDING","HUMAN_ASSESSMENT_CERTIFICATION_PENDING","ADAPTIVE_CALIBRATION_PENDING","LIVE_STUDENT_DELIVERY_DISABLED"]'::jsonb)
on conflict(course_id) do update set content_version='v29.0',assessment_version='v29.1',adaptive_calibration_status='heuristic_candidate',
 human_content_review_required=true,human_assessment_review_required=true,live_student_delivery=false,release_candidate=false,
 blocker_codes=excluded.blocker_codes,updated_at=now();

insert into public.curriculum_sources_v254(source_key,course_id,kind,title,url,authority,notes)
select source_key,course_id,kind,title,url,authority,notes
from jsonb_to_recordset($sources$[{"source_key":"mineduc-5b-course","course_id":"cl-5-basico","kind":"official_curriculum_page","title":"Matemática 5.º básico","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico","authority":"UCE Mineduc","notes":"Currículo oficial actualmente publicado."},{"source_key":"mineduc-5b-program","course_id":"cl-5-basico","kind":"official_program","title":"Programa de Estudio Matemática 5.º básico","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-5-basico","authority":"UCE Mineduc","notes":"Programa oficial consultado para la organización del nivel."},{"source_key":"mineduc-5b-update-1b-2m","course_id":"cl-5-basico","kind":"official_update_process","title":"Actualización Curricular 1.º básico a 2.º medio","url":"https://www.curriculumnacional.cl/actualizacion-curricular","authority":"Mineduc","notes":"Proceso en seguimiento; requiere revalidación antes de release."},{"source_key":"mineduc-5b-oa-01","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 01","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-01","authority":"UCE Mineduc","notes":"Representar y describir números naturales de hasta más de seis dígitos y menores que 1 000 millones: identificando el valor posicional de los dígitos; componiendo y descomponiendo números en forma estándar y expandida; aproximando cantidades; comparando y ordenando números; dando ejemplos de estos números en contextos reales.","source_sha256":"38b72e39962e201bc622d446dd186774a6f14555b2abc7b51d9200c049c068ec","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-02","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 02","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-02","authority":"UCE Mineduc","notes":"Aplicar estrategias de cálculo mental para la multiplicación: anexar ceros cuando se multiplica por un múltiplo de 10; doblar y dividir por 2 en forma repetida; usar las propiedades conmutativa, asociativa y distributiva.","source_sha256":"f7b8aec61562995b8afe6d5d55aacd5eba7599fbabfaa9b8f270bac13380fb3e","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-03","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 03","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-03","authority":"UCE Mineduc","notes":"Demostrar que comprenden la multiplicación de números naturales de dos dígitos por números naturales de dos dígitos: estimando productos; aplicando estrategias de cálculo mental; resolviendo problemas rutinarios y no rutinarios; aplicando el algoritmo de la multiplicación.","source_sha256":"c278aaa08e5918ff244a9607b4e47fa2b721fe5610d473226fa0fb15188b874d","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-04","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 04","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-04","authority":"UCE Mineduc","notes":"Demostrar que comprenden la división con dividendos de tres dígitos y divisores de un dígito: interpretando el resto; resolviendo problemas rutinarios y no rutinarios; usando estrategias para dividir; aplicando la relación inversa entre la división y la multiplicación; aplicando el algoritmo de la división.","source_sha256":"688ec125bf77c15fbb5089b9587cb669de5d2bbb14822fd70cb4854d61a57304","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-05","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 05","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-05","authority":"UCE Mineduc","notes":"Realizar cálculos que involucren las cuatro operaciones, aplicando las reglas relativas a paréntesis y la prevalencia de la multiplicación y la división por sobre la adición y la sustracción cuando corresponda.","source_sha256":"8952c48c6b07186cd0ec2e66b4068db5afa933318625eb65599ac91c7b180e93","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-06","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 06","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-06","authority":"UCE Mineduc","notes":"Resolver problemas rutinarios y no rutinarios que involucren las cuatro operaciones y combinaciones de ellas: que incluyan situaciones con dinero; usando la calculadora y el computador en ámbitos numéricos superiores a 10 000.","source_sha256":"4e1d50f91f0878abfe8e6cdac3b1156956849b0948e67638549cb3194bc0fa5e","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-07","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 07","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-07","authority":"UCE Mineduc","notes":"Demostrar que comprenden las fracciones propias: representándolas de manera concreta, pictórica y simbólica; creando grupos de fracciones equivalentes, simplificando y amplificando; comparando fracciones propias con igual y distinto denominador; comparando fracciones propias con igual y distinto numerador.","source_sha256":"2e4701858d434dfd76f02b3140c87ecd9e5e2d43be863bf192be09d1a0d2842c","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-08","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 08","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-08","authority":"UCE Mineduc","notes":"Demostrar que comprenden las fracciones impropias de uso común de denominadores 2, 3, 4, 5, 6, 8, 10, 12 y los números mixtos asociados, usando material concreto y pictórico para representarlos, identificando equivalencias y representándolos en la recta numérica.","source_sha256":"9c3d19a1d45b176d4f969927e08e88873cdf52fb44e7b3c4e6bb7df92c1eedf4","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-09","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 09","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-09","authority":"UCE Mineduc","notes":"Resolver adiciones y sustracciones con fracciones propias con denominadores menores o iguales a 12, de manera pictórica y simbólica.","source_sha256":"a3cd6bf3fdd44e1b3f9c9d022da35607614e3e0157a25f79e6874a4057dad5c6","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-10","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 10","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-10","authority":"UCE Mineduc","notes":"Determinar el decimal que corresponde a fracciones con denominador 2, 4, 5 y 10.","source_sha256":"f072df8ad6d026fb8035bf00de9ce417151879d4d63e6e5913267d3049d439d5","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-11","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 11","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-11","authority":"UCE Mineduc","notes":"Comparar y ordenar decimales hasta la milésima.","source_sha256":"4cef1c685b8848c67d9c977fc64333620c0fd040df55c42da8f5572b69c3e028","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-12","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 12","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-12","authority":"UCE Mineduc","notes":"Resolver adiciones y sustracciones de decimales, empleando el valor posicional hasta la milésima.","source_sha256":"a0dd6d6c3d7d861f458a1e65ee5010b28414ce9fd440a131e9b95e833c8a270e","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-13","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 13","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-13","authority":"UCE Mineduc","notes":"Resolver problemas rutinarios y no rutinarios, aplicando adiciones y sustracciones de fracciones propias o decimales hasta la milésima.","source_sha256":"638f409eafaf5bca233585abbb4ee566eeaaf0761e0ec3194ba7802075b5ac15","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-14","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 14","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-14","authority":"UCE Mineduc","notes":"Descubrir alguna regla que explique una sucesión dada y que permita hacer predicciones.","source_sha256":"21a294ac34909cee452e4a81df7d3a2aea47f40547751d6bdbeec533c60921ee","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-15","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 15","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-15","authority":"UCE Mineduc","notes":"Resolver problemas usando ecuaciones e inecuaciones de un paso que involucren adiciones y sustracciones, en forma pictórica y simbólica.","source_sha256":"ae5eee3f35808343144e6a3af1b0b05f949335ba3e969ca6ee0870dca787968c","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-16","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 16","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-16","authority":"UCE Mineduc","notes":"Identificar y dibujar puntos en el primer cuadrante del plano cartesiano, dadas sus coordenadas en números naturales.","source_sha256":"3ee1a2fac8b661d583f3b7ffa4f364255acf0cb6bf988d542099ae9b26e587bf","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-17","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 17","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-17","authority":"UCE Mineduc","notes":"Describir y dar ejemplos de aristas y caras de figuras 3D y lados de figuras 2D que son paralelos, que se intersectan o que son perpendiculares.","source_sha256":"2d36ab562b09d5b78417d0ce8f94dc5def212a6e20c376af643c7b7175e3a1e9","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-18","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 18","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-18","authority":"UCE Mineduc","notes":"Demostrar que comprenden el concepto de congruencia, usando la traslación, la reflexión y la rotación en cuadrículas y mediante software geométrico.","source_sha256":"d7c4b7c01d8d2ceda276ce75d05069f0247a794e9dfa351899eade29597420f6","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-19","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 19","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-19","authority":"UCE Mineduc","notes":"Medir longitudes con unidades estandarizadas, metros, centímetros y milímetros, en el contexto de la resolución de problemas.","source_sha256":"4c3a950ea7ee868bea8580a7f2279acde7397a3214ba7c08df1100ddd88257f8","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-20","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 20","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-20","authority":"UCE Mineduc","notes":"Realizar transformaciones entre unidades de medidas de longitud, kilómetros a metros, metros a centímetros, centímetros a milímetros y viceversa, de manera manual y/o usando software educativo.","source_sha256":"c48b6ba96d7e79fe0172e64d215322109940dbcbceea4f599f36528b03f43dbc","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-21","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 21","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-21","authority":"UCE Mineduc","notes":"Diseñar y construir diferentes rectángulos, dados el perímetro, el área o ambos, y sacar conclusiones.","source_sha256":"dc70803bca79dde7496e148cfed13648fdb0a515126653fa5fa6a98a093f9e6c","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-22","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 22","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-22","authority":"UCE Mineduc","notes":"Calcular áreas de triángulos, de paralelogramos y de trapecios, y estimar áreas de figuras irregulares aplicando estrategias pertinentes.","source_sha256":"c6801c8cefb1d1c07cff8b545c73b80f3b5171dfce4b22005b59b3c36dd6b674","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-23","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 23","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-23","authority":"UCE Mineduc","notes":"Calcular el promedio de datos e interpretarlo en su contexto.","source_sha256":"c782cd0577e7c4e582de2191618974af7608b20adf461e6f6bffff6447f05fec","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-24","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 24","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-24","authority":"UCE Mineduc","notes":"Describir la posibilidad de ocurrencia de un evento en base a un experimento aleatorio, empleando los términos seguro, posible, poco posible o imposible.","source_sha256":"686cf7ec1c38263fb76c701a49d500ee207b608a13b1e89f85d42ccb064174e5","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-25","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 25","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-25","authority":"UCE Mineduc","notes":"Comparar probabilidades de distintos eventos sin calcularlas.","source_sha256":"4e71806c48845d679c9d7bc069bf0b97515a96ca02c4a75b71a558bee6703362","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-26","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 26","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-26","authority":"UCE Mineduc","notes":"Leer, interpretar y completar tablas, gráficos de barra simple y gráficos de línea, y comunicar sus conclusiones.","source_sha256":"17cc18513c54bd43e3566f93d02cc78eeda332f5b10f50c4776e3a8d6ea139a2","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-oa-27","course_id":"cl-5-basico","kind":"official_oa","title":"MA05 OA 27","url":"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/matematica/5-basico/ma05-oa-27","authority":"UCE Mineduc","notes":"Utilizar diagramas de tallo y hojas para representar datos provenientes de muestras aleatorias.","source_sha256":"f3d32865f2e0c6fc40b78640b71242c9f91ee301381e378f95036e23572bd7cc","source_status":"normalized_official_statement"},{"source_key":"mineduc-5b-u1","course_id":"cl-5-basico","kind":"official_program_unit","title":"U1: Números naturales y operaciones.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-5-basico","authority":"UCE Mineduc","notes":"Unidad de organización del macrobloque basada en el programa oficial."},{"source_key":"mineduc-5b-u2","course_id":"cl-5-basico","kind":"official_program_unit","title":"U2: Localización, figuras 2D y 3D, congruencia y medición.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-5-basico","authority":"UCE Mineduc","notes":"Unidad de organización del macrobloque basada en el programa oficial."},{"source_key":"mineduc-5b-u3","course_id":"cl-5-basico","kind":"official_program_unit","title":"U3: Fracciones, decimales, patrones, ecuaciones e inecuaciones.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-5-basico","authority":"UCE Mineduc","notes":"Unidad de organización del macrobloque basada en el programa oficial."},{"source_key":"mineduc-5b-u4","course_id":"cl-5-basico","kind":"official_program_unit","title":"U4: Promedio, probabilidad y representación de datos.","url":"https://www.curriculumnacional.cl/recursos/programa-estudio-matematica-5-basico","authority":"UCE Mineduc","notes":"Unidad de organización del macrobloque basada en el programa oficial."}]$sources$::jsonb)
